BEGIN;
CREATE TABLE IF NOT EXISTS business_plan_templates (id UUID PRIMARY KEY,flow TEXT NOT NULL CHECK(flow IN ('master','tenant')),family TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),name TEXT NOT NULL,payload JSONB NOT NULL,published_by TEXT NOT NULL,published_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(flow,family,version));
CREATE TABLE IF NOT EXISTS business_plan_cycles (id UUID PRIMARY KEY,tenant_id TEXT NOT NULL,name TEXT NOT NULL,data JSONB NOT NULL,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS business_plan_cycles_scope ON business_plan_cycles(tenant_id,created_at DESC,id);
CREATE TABLE IF NOT EXISTS business_plan_lessons (id UUID PRIMARY KEY,tenant_id TEXT NOT NULL,cycle_id UUID NOT NULL REFERENCES business_plan_cycles(id),template_id UUID NOT NULL REFERENCES business_plan_templates(id),data JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','published','rejected')),submitted_by TEXT NOT NULL,reviewed_by TEXT,review_reason TEXT,published_template_id UUID REFERENCES business_plan_templates(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS business_plan_audit (id UUID PRIMARY KEY,tenant_id TEXT NOT NULL,cycle_id UUID REFERENCES business_plan_cycles(id),actor_id TEXT NOT NULL,action TEXT NOT NULL,detail JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS business_plan_requests (actor_id TEXT NOT NULL,key TEXT NOT NULL,fingerprint TEXT NOT NULL,response JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(actor_id,key));
CREATE TABLE IF NOT EXISTS business_plan_notices (id UUID PRIMARY KEY,tenant_id TEXT,recipient_id TEXT,roles JSONB NOT NULL,title TEXT NOT NULL,message TEXT NOT NULL,cycle_id UUID REFERENCES business_plan_cycles(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS business_plan_notice_reads (notice_id UUID NOT NULL REFERENCES business_plan_notices(id),user_id TEXT NOT NULL,read_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(notice_id,user_id));
INSERT INTO business_plan_notices(id,roles,title,message) VALUES ('cebc06aa-9464-4fe1-bf4d-bbd881581801','["code_admin","platform_admin","central_admin","ceo","owner","tenant_admin","marketing","local_marketing","growth_caller","growth_google","growth_meta","growth_seo","growth_offline","growth_coordinator"]','Your six-month business planning tools are ready','Managers: choose a template, confirm your baseline and capacity, allocate named owners, then set a start date. Team members: open assigned tasks, record evidence and submit for manager review. Review gaps weekly and use the learning review to improve future templates. Targets are planning assumptions, not guaranteed results.') ON CONFLICT(id) DO NOTHING;
COMMIT;
